173: // Single hop of the trace; the engine moves the request one stage per call,
174: // originating from whichever browser is currently expanded on Ring 3.
175: function stepOneHop() {
176:   const snapshot = engine.traceHop({
177:     method: els.method.value,
178:     path: els.urlInput.value,
179:     from: activeBrowserAddress,
180:   });
181:   const totalHops = traceFinalHop(snapshot, snapshot.stage);
182:   // PINS: hop 1 emission starts a new trace run — that run (whole, hops
183:   // ascending) floats above the previous run in #journey-log.
184:   // CHECKS: when the trace's final hop lands, the run's stored labels are
185:   // relabeled to the final denominator (an NX run's early `hop 1/9` estimate
186:   // must not survive into the finished log, which ends at hop 2).
187:   if (snapshot.trace.hop === 1) traceRunId = nextJourneyRun();
188:   addToJourney(`hop ${snapshot.trace.hop}/${totalHops}`, snapshot.lastFrame, {
189:     run: traceRunId,
190:     hop: snapshot.trace.hop,
191:   });
192:   if (snapshot.trace.hop === traceFinalHop(snapshot, snapshot.stage)) {
193:     relabelJourneyRun(traceRunId, totalHops);
194:   }
195:   updateView(snapshot);
196:   return snapshot;
197: }
