140: function formatHopStatus(snapshot, serverAddress) {
141:   const hop = snapshot.trace?.hop ?? 0;
142:   const from = snapshot.trace?.from ?? '10.2';
143:   if (hop >= 1) {
144:     const sentences = hopSentences(snapshot.stage ?? 1, snapshot, from, serverAddress);
145:     if (hop <= sentences.length) return sentences[hop - 1];
146:   }
147:   return HOP_START_SENTENCE;
148: }
