### model.js additions (~40 lines)

```js
// B-5 compare tray — pure slot/align contracts (compare.js consumes them;
// DOM-free here so the unit suite pins the branches).

// PINS: verbatim passthrough — alignCompareRows reads each side's own entry
// texts by hop index and never mutates them; an exhausted side renders the
// em-dash cell. Counter-example (pinned): 9-by-6 runs produce 9 rows with
// rows 7-9 right cells '—', and nothing drops.
export function alignCompareRows(left, right) {
  const rows = [];
  const total = Math.max(left.hops, right.hops);
  for (let n = 1; n <= total; n += 1) {
    rows.push({
      n,
      left: left.entries.find((entry) => entry.hop === n)?.text ?? '—',
      right: right.entries.find((entry) => entry.hop === n)?.text ?? '—',
    });
  }
  return rows;
}
```

