```js
// CHECKS (B-5): slot branch — a run enters only with hops >= 2 and at least
// one hop entry (tick-shaped runs — hops 0 — are rejected here, the
// trace-runs-only counter-example's purity pin: crowd ticks must not shift
// slots); a run whose id matches an occupied slot is a no-op (the tray does
// not duplicate); otherwise filling fills A then B, and a third distinct run
// shifts A <- old B, B <- new.
export function nextCompareSlots(slots, newRun) {
  if (!newRun || newRun.hops < 2 || !Array.isArray(newRun.entries) || newRun.entries.length === 0) {
    return { a: slots.a, b: slots.b, changed: false };
  }
  if (
    (slots.a && slots.a.run === newRun.run) ||
    (slots.b && slots.b.run === newRun.run)
  ) {
    return { a: slots.a, b: slots.b, changed: false };
  }
  if (!slots.a) return { a: newRun, b: slots.b, changed: true };
  if (!slots.b) return { a: slots.a, b: newRun, changed: true };
  return { a: slots.b, b: newRun, changed: true };
}
```

