  const hopEntry = (run, hop, text) => ({ run, hop, label: `hop ${hop}/x`, text });
  // A run record shaped exactly as the completion branch builds it:
  // one entry per hop, hop-ascending, verbatim frame texts.
  const mkRun = (run, hops, prefix) => ({
