  // entries are never mutated (compare never mints hop text).
  it('passes entry texts through verbatim without mutating the runs', () => {
    const left = mkRun(1, 3, 'L');
    const right = mkRun(2, 2, 'R');
    const leftTexts = left.entries.map((e) => e.text);
    const rightTexts = right.entries.map((e) => e.text);
    const rows = alignCompareRows(left, right);
    expect(rows.map((r) => r.left)).toEqual(leftTexts);
    expect(rows.map((r) => r.right)).toEqual([...rightTexts, '—']);
    expect(left.entries.map((e) => e.text)).toEqual(leftTexts);
    expect(right.entries.map((e) => e.text)).toEqual(rightTexts);
  });

