    const three = mkRun(3, 4, 'C');
    let next = nextCompareSlots(empty, one);
    expect(next).toEqual({ a: one, b: null, changed: true });
    next = nextCompareSlots({ a: next.a, b: next.b }, two);
    expect(next).toEqual({ a: one, b: two, changed: true });
    next = nextCompareSlots({ a: next.a, b: next.b }, three);
    expect(next).toEqual({ a: two, b: three, changed: true });
  });

