+  // one entry per hop, hop-ascending, verbatim frame texts.
+  const mkRun = (run, hops, prefix) => ({
+    run,
+    hops,
+    label: `run ${run}`,
+    entries: Array.from({ length: hops }, (_, i) => hopEntry(run, i + 1, `${prefix}${i + 1} frame`)),
+  });
+  const empty = { a: null, b: null };
+
+  // PINS: the named counter-example — 9-by-6 runs produce 9 rows with rows
+  // 7-9 right cells '—', and no frame drops.
+  it('aligns unequal 9-by-6 runs into 9 rows with rows 7-9 right cells as em-dashes', () => {
+    const rows = alignCompareRows(mkRun(1, 9, 'L'), mkRun(2, 6, 'R'));
+    expect(rows).toHaveLength(9);
+    expect(rows.map((r) => r.n)).toEqual([1, 2, 3, 4, 5, 6, 7, 8, 9]);
+    expect(rows[0]).toEqual({ n: 1, left: 'L1 frame', right: 'R1 frame' });
+    expect(rows[5].right).toBe('R6 frame');
+    expect(rows[6].right).toBe('—');
+    expect(rows[8]).toEqual({ n: 9, left: 'L9 frame', right: '—' });
+  });
+
+  it('aligns equal runs hop-for-hop, n counted from 1', () => {
+    const rows = alignCompareRows(mkRun(1, 4, 'L'), mkRun(2, 4, 'R'));
+    expect(rows).toHaveLength(4);
+    expect(rows[3]).toEqual({ n: 4, left: 'L4 frame', right: 'R4 frame' });
+  });
+
+  // PINS: verbatim passthrough — texts are byte-identical and the input
+  // entries are never mutated (compare never mints hop text).
+  it('passes entry texts through verbatim without mutating the runs', () => {
+    const left = mkRun(1, 3, 'L');
+    const right = mkRun(2, 2, 'R');
+    const leftTexts = left.entries.map((e) => e.text);
+    const rightTexts = right.entries.map((e) => e.text);
+    const rows = alignCompareRows(left, right);
+    expect(rows.map((r) => r.left)).toEqual(leftTexts);
+    expect(rows.map((r) => r.right)).toEqual([...rightTexts, '—']);
+    expect(left.entries.map((e) => e.text)).toEqual(leftTexts);
+    expect(right.entries.map((e) => e.text)).toEqual(rightTexts);
+  });
+
+  it('fills A then B, and a third distinct run shifts A <- old B, B <- new', () => {
+    const one = mkRun(1, 4, 'A');
+    const two = mkRun(2, 4, 'B');
+    const three = mkRun(3, 4, 'C');
+    let next = nextCompareSlots(empty, one);
+    expect(next).toEqual({ a: one, b: null, changed: true });
+    next = nextCompareSlots({ a: next.a, b: next.b }, two);
+    expect(next).toEqual({ a: one, b: two, changed: true });
+    next = nextCompareSlots({ a: next.a, b: next.b }, three);
+    expect(next).toEqual({ a: two, b: three, changed: true });
+  });
+
+  // PINS: the two-distinct-runs counter-example — a completed run matching
+  // a stored slot's run id is a no-op (the tray does not duplicate).
+  it('re-pushing a run already in a slot is a no-op (changed false, slots unchanged)', () => {
+    const one = mkRun(1, 4, 'A');
+    const two = mkRun(2, 4, 'B');
